import @vibe/compiler/core { Expr }
import @vibe/compiler/codegen/common_analysis { collect_free_vars_indexed }
import @vibe/core { sorted_names_of }

fn main allows Console {
  let globals: Array[String] = []
  let calls: Array[Expr] = []
  let params: Array[String] = []
  let mut i = 0
  while i < 256 {
    let name = "global_\{i}"
    Array::push(globals, name)
    Array::push(calls, ECall(EIdent(name, -1), [], -1))
    i = i + 1
  }
  i = 0
  while i < 16 {
    Array::push(params, "local_\{i}")
    i = i + 1
  }
  let names = sorted_names_of(globals)
  let body = ETuple(calls)
  let mut total = 0
  i = 0
  while i < 100 {
    total = total + Array::length(collect_free_vars_indexed(body, params, names))
    i = i + 1
  }
  println("\{total}")
}
